/* @lc app=leetcode id=3348 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun fd(r: Long): List<Int>? = (9 downTo 2).fold(r to listOf<Int>()) { (x, l), d -> generateSequence(x to l) { (y, ll) -> if (y % d == 0L) y / d to ll + d else null }.last() }.let { (x, l) -> if (x == 1L) l.sorted() else null } fun smallestNumber(num: String, t: Long): String = num.length.let { n -> (num.indexOf('0').let { if (it < 0) n - 1 else it }).let { z -> num.take(z).fold(listOf(t)) { l, c -> l + l.last() / g(l.last(), (c - '0').toLong()) }.let { rems -> if ('0' !in num && num.fold(t) { r, c -> r / g(r, (c - '0').toLong()) } == 1L) num else (z downTo 0).firstNotNullOfOrNull { i -> ((num[i] - '0' + 1)..9).firstNotNullOfOrNull { d -> fd(rems[i] / g(rems[i], d.toLong()))?.takeIf { it.size <= n - i - 1 }?.let { l -> num.take(i) + d + "1".repeat(n - i - 1 - l.size) + l.joinToString("") } } } ?: (fd(t)?.let { l -> "1".repeat(maxOf(0, n + 1 - l.size)) + l.joinToString("") } ?: "-1") } } } }